const icon = (name, cls = "") => `<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const euro = value => new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(value);
const badge = (label, tone = "gray") => `<span class="badge badge-${tone}">${label}</span>`;
const personCell = person => `<div class="person-cell"><span class="avatar ${person.avatar}">${person.initials}</span><span><strong>${person.name}</strong><small>${person.role} · ${person.team}</small></span></div>`;
const plural = (count, singular, pluralForm) => `${count} ${count > 1 ? pluralForm : singular}`;
const needExpressionCount = need => Object.entries(need.sources || {}).reduce((total, [source, count]) => source === "obligation" ? total : total + count, 0);
const needPopulation = need => need.targetPopulation ?? Math.max(0, needExpressionCount(need) - (need.duplicates || 0));
const needSourceSummary = need => {
  const parts = [];
  if (need.sources?.interviews) parts.push(plural(need.sources.interviews, "entretien", "entretiens"));
  if (need.sources?.spontaneous) parts.push(plural(need.sources.spontaneous, "demande spontanée", "demandes spontanées"));
  if (need.sources?.manager) parts.push(plural(need.sources.manager, "demande manager", "demandes manager"));
  if (need.sources?.obligation) parts.push("Obligation entreprise");
  return parts.join(" + ");
};
const needPopulationFormula = need => need.targetPopulation
  ? `Population ciblée par l'obligation : ${need.targetPopulation}`
  : `${needSourceSummary(need)}${need.duplicates ? ` − ${plural(need.duplicates, "doublon", "doublons")}` : ""} = ${plural(needPopulation(need), "collaborateur unique", "collaborateurs uniques")}`;
const selectedEmployee = () => people.find(person => person.id === state.selectedEmployeeId) || people[0];
const selectedProfile = () => employeeProfiles[state.selectedEmployeeId] || employeeProfiles[1];
const selectedHistory = () => employeeHistories[state.selectedEmployeeId] || employeeHistories[1];

