function interviewHistoryView() {
  const employeeMode = state.role === "employee";
  const person = selectedEmployee();
  const profile = selectedProfile();
  const history = selectedHistory();
  const completed = history.filter(record => record.status === "Finalisé").length;
  const actionCount = history.reduce((total, record) => total + record.actions, 0);
  const cards = history.map(record => { const current = record.status !== "Finalisé"; return `<article class="history-record ${current ? "current" : ""}">
    <div class="history-year"><strong>${record.year}</strong><span>${current ? "En cours" : "Archivé"}</span></div>
    <div class="history-record-main"><div class="history-record-title"><div><h3>${record.type}</h3><p>${record.reason}</p></div>${badge(record.status, record.tone)}</div><div class="history-record-meta"><span><small>Date</small><strong>${record.date}</strong></span><span><small>Conducteur</small><strong>${record.conductor}</strong></span><span><small>Document</small><strong>${record.version}</strong></span><span><small>Remise</small><strong>${record.delivery}</strong></span></div><div class="history-record-foot"><span>${record.actions} actions de suivi</span><div>${current ? (person.id === 1 ? `<button class="btn btn-primary btn-sm" data-nav="${employeeMode ? "my-interview" : "interview-form"}">${employeeMode ? "Voir ma préparation" : "Continuer la préparation"}</button>` : `<button class="btn btn-primary btn-sm" data-action="mock-other-prep">Consulter l'échéance</button>`) : `<button class="btn btn-secondary btn-sm" data-history-report="${record.id}">${icon("doc")}Consulter le compte rendu</button><button class="btn btn-ghost btn-sm" data-action="export">${icon("download")}Télécharger</button>`}</div></div></div>
  </article>`; }).join("");
  return `${pageHead(employeeMode ? "Mon parcours" : `Collaborateurs / ${person.name}`, "Historique des entretiens", "Consultez les entretiens, leurs versions, les preuves de remise et les actions associées.", employeeMode ? `<button class="btn btn-secondary" data-nav="my-documents">Retour à mes documents</button>` : `<button class="btn btn-secondary" data-nav="employee-detail">Retour au dossier</button>${person.id === 1 ? `<button class="btn btn-primary" data-nav="interview-form">Préparer l'entretien 2026</button>` : ""}`)}
    <section class="history-person"><span class="avatar ${person.avatar}">${person.initials}</span><div><strong>${person.name}</strong><small>${person.role} · Matricule ${profile.employeeNumber}</small></div><div class="history-person-stats"><span><strong>${history.length}</strong><small>entretiens</small></span><span><strong>${completed}</strong><small>comptes rendus remis</small></span><span><strong>${actionCount}</strong><small>actions suivies</small></span></div></section>
    <div class="history-toolbar"><div class="segmented"><button class="active">Tous</button><button>Finalisés</button><button>En cours</button></div><span>${icon("shield")} Historique fictif · ${employeeMode ? "accès personnel simulé" : "accès RH simulé"}</span></div>
    <section class="history-records">${cards}</section>`;
}

