      <section class="report-section"><div class="report-section-number">03</div><div><h3>Actions décidées</h3>${actions.map(action => `<div class="report-action"><span><strong>${action.title}</strong><small>${action.result}</small></span>${badge(action.status, action.tone)}</div>`).join("") || `<p>Aucune action structurée dans ce compte rendu.</p>`}</div></section>
